/** @fileoverview Popular files list component. Renders a ranked table of the
 * most-accessed files sourced from the stats.top10.json report generated by
 * the ConnectBox content pipeline. Shown only at the root path. */

import './FolderList.css'
import './PopularFileList.css'

import React, { Component } from 'react'
import PropTypes from 'prop-types'
import PopularFileListEntry from './PopularFileListEntry'

/**
 * Renders a table of popular files with a chart-icon header row.
 * Uses an imperative for-loop instead of Array.map so the null-guard on
 * popularFiles can be applied without an extra conditional wrapper.
 */
class PopularFileList extends Component {
    static propTypes = {
      popularFiles: PropTypes.array.isRequired
    }

  /**
   * Builds the list of PopularFileListEntry rows and wraps them in a
   * responsive table. The first entry hides its top border so it visually
   * connects to the header row above it.
   * @returns {JSX.Element}
   */
  render () {
    const { popularFiles } = this.props
    const popularFileElements = []
    // Guard against popularFiles being null before the async fetch resolves
    for (let i = 0; popularFiles && i < popularFiles.length; i++) {
      const file = popularFiles[i]

      popularFileElements.push(
        <PopularFileListEntry
          key={`pop${i}`}
          file={file}
          hideTopBorder={i === 0}
        />
      )
    }

    return (
      <div className="table-responsive">
        <table className="table">
            <tbody>
                <tr><td className="popular-content-header"><i className="fa fa-line-chart"></i></td></tr>
                {popularFileElements}
            </tbody>
        </table>
      </div>
    )
  }
}

export default PopularFileList
